# --- 「활용 1편」의 문제를 테스트로 재현 ---

#   1편 8.10절: merge 는 안 보낸 필드를 null 로 덮는다

@Test
void merge_는_안_보낸_필드를_null_로_덮는다() {
    // given
    Item saved = itemRepository.save(new Book("JPA", 10000, 100, "kim", "111"));

    Book param = new Book();
    param.setId(saved.getId());
    param.setName("JPA 2판");
    param.setPrice(20000);
    // author 와 isbn 을 안 넣었다

    // when
    itemRepository.save(param);   // merge

    // then
    Item found = itemRepository.findById(saved.getId()).orElseThrow();
    assertThat(((Book) found).getAuthor()).isEqualTo("kim");
}

$ ./gradlew test --tests ItemRepositoryTest

ItemRepositoryTest > merge_는_안_보낸_필드를_null_로_덮는다 FAILED
    org.opentest4j.AssertionFailedError:
    expected: "kim"
     but was: null

#   1편 8.10절이 글로 설명한 것이 빨간 막대 하나로 나온다

