#   변경 감지로 바꿀 때 자동으로 초록이 된다

# --- 활용 2편 7.3절의 동시 가입 ---

@Test
void 같은_이름으로_동시에_가입하면_둘_다_들어간다() throws Exception {
    // given
    int threads = 10;
    CountDownLatch latch = new CountDownLatch(threads);
    ExecutorService es = Executors.newFixedThreadPool(threads);

    // when
    for (int i = 0; i < threads; i++) {
        es.submit(() -> {
            try { memberService.join(createMember("동시가입")); }
            catch (Exception ignored) { }
            finally { latch.countDown(); }
        });
    }
    latch.await();

    // then
    assertThat(memberRepository.findByName("동시가입")).hasSize(1);
}

$ ./gradlew test --tests MemberConcurrencyTest

MemberConcurrencyTest > 같은_이름으로_동시에_가입하면_둘_다_들어간다 FAILED
    java.lang.AssertionError:
    Expected size: 1 but was: 7 in:
    [Member(id=1, name=동시가입), Member(id=2, name=동시가입), ...]

