# --- 활용 2편 5.7절의 쿼리 개수 ---

@Test
void 주문_목록은_쿼리_세_개로_조회된다() {
    // given
    Statistics stats = entityManagerFactory.unwrap(SessionFactory.class)
                                           .getStatistics();
    stats.clear();

    // when
    orderQueryService.findOrders(0, 100);

    // then
    assertThat(stats.getPrepareStatementCount()).isEqualTo(3);
}

